    sources=[dict(id='chaos-theory-'+i+'-v1',technique_id=59,rank=rank,author=author,edition=edition,url=url,locator=locator,ingestion='facts_only',rights_note='Copyright retained by source owners; mathematical facts and original synthetic fixtures only; no bodies,figures,data or third-party code redistributed.',checked_on='2026-11-08',snapshot_sha256=None,snapshot_bytes=None) for i,rank,author,edition,url,locator in specs]
